 ( 
     ${session.HOUSE_CODE}
   , ${session.COMPANY_CODE}
   , ${USER_ID}
   , ${APP_LINE_CODE}
   , ${APP_LINE_NAME}
   , ${current.DATE}
   , ${current.TIME}
   , ${session.ID}
   , 'N'
 )
